//! Tier 1 — completeness check.
//!
//! Parses `sd-event.h` (path provided by `build.rs` via `SD_EVENT_HEADER`)
//! and `src/sys.rs`, extracts every `sd_event_*` function name from each,
//! and fails if the header declares anything the sys module doesn't bind.
#![deny(unsafe_code)]

use std::collections::BTreeSet;

const HEADER: &str = include_str!(env!("SD_EVENT_HEADER"));
const SYS: &str = include_str!("../src/sys.rs");

/// Symbols generated by the `_SD_DECLARE_TRIVIAL_REF_UNREF_FUNC` macros in
/// the header. These are real exported symbols but never appear as plain
/// function declarations, so we add them by hand.
const REF_UNREF_MACRO_SYMBOLS: &[&str] = &[
    "sd_event_ref",
    "sd_event_unref",
    "sd_event_source_ref",
    "sd_event_source_unref",
];

/// Names ending in these suffixes come from
/// `_SD_DEFINE_POINTER_CLEANUP_FUNC` and are `static inline` helpers for
/// GCC's `__attribute__((cleanup))` — not exported symbols, so we skip
/// them on both sides.
const INLINE_CLEANUP_SUFFIXES: &[&str] = &["_unrefp", "_disable_unrefp"];

fn is_ident(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

/// Find every `sd_event_*` identifier immediately followed by `(` in
/// `text`. Works for both the C header (function declarations) and our
/// `sys.rs` (`pub fn sd_event_xxx(...)` lines).
fn extract_called_names(text: &str) -> BTreeSet<String> {
    let bytes = text.as_bytes();
    let needle = b"sd_event_";
    let mut out = BTreeSet::new();
    let mut i = 0;
    while i + needle.len() <= bytes.len() {
        if &bytes[i..i + needle.len()] != needle {
            i += 1;
            continue;
        }
        if i > 0 && is_ident(bytes[i - 1]) {
            i += 1;
            continue;
        }
        let mut j = i + needle.len();
        while j < bytes.len() && is_ident(bytes[j]) {
            j += 1;
        }
        let mut k = j;
        while k < bytes.len() && (bytes[k] == b' ' || bytes[k] == b'\t') {
            k += 1;
        }
        if k < bytes.len() && bytes[k] == b'(' {
            let name = std::str::from_utf8(&bytes[i..j]).unwrap().to_string();
            if !INLINE_CLEANUP_SUFFIXES
                .iter()
                .any(|suf| name.ends_with(suf))
            {
                out.insert(name);
            }
        }
        i = j.max(i + 1);
    }
    out
}

#[test]
fn every_header_function_is_bound() {
    let mut header = extract_called_names(HEADER);
    for s in REF_UNREF_MACRO_SYMBOLS {
        header.insert((*s).into());
    }

    let sys = extract_called_names(SYS);

    let missing: Vec<&String> = header.difference(&sys).collect();
    assert!(
        missing.is_empty(),
        "sd-event.h declares {} symbol(s) not bound in src/sys.rs:\n  {}",
        missing.len(),
        missing
            .iter()
            .map(|s| s.as_str())
            .collect::<Vec<_>>()
            .join("\n  "),
    );

    let extras: Vec<&String> = sys.difference(&header).collect();
    assert!(
        extras.is_empty(),
        "src/sys.rs binds {} symbol(s) not declared in sd-event.h:\n  {}",
        extras.len(),
        extras
            .iter()
            .map(|s| s.as_str())
            .collect::<Vec<_>>()
            .join("\n  "),
    );
}
